/* ---- kurulum: indeks + 100luk paketler ---- */
const B1_PACK_SIZE = 100;
B1.forEach((w, i) => { w._i = i; w.pack = Math.floor(i / B1_PACK_SIZE) + 1; });

/* paket listesi: {id, count, from, to} — filtre panelinde kullanilir */
const B1_PACKS = (function () {
  const m = new Map();
  B1.forEach(w => {
    if (!m.has(w.pack)) m.set(w.pack, { id: w.pack, count: 0, from: w.en, to: w.en });
    const p = m.get(w.pack); p.count++; p.to = w.en;
  });
  return Array.from(m.values());
})();

/* veride gercekten bulunan turler (ilk gorulme sirasina gore) */
const B1_POS = (function () {
  const m = new Map();
  B1.forEach(w => { if (!m.has(w.pos)) m.set(w.pos, { id: w.pos, count: 0 }); m.get(w.pos).count++; });
  return Array.from(m.values()).sort((a, b) => b.count - a.count);
})();
